"""第二人：全文 → 摘要 → 無可用證據的單一入口（不連網）。

重點：
1. 順序正確，拿到全文就不浪費一次 Semantic Scholar 額度
2. 同一筆 ref 只解析一次，方法 A 和方法 B 拿到同一份證據
3. 全文和摘要各自為什麼沒拿到要分開寫，不可以併成一句「查詢失敗」
"""

import pytest

from src.adapters import ReferenceLookupResult
from src.fulltext_sources import FullTextResult, FullTextStatus
from src.schemas import CitationPair, EvidenceBasis, SourceStatus
from src.source_evidence import EvidenceResolver

REF = ("[1] W. H. Walters and E. I. Wilder, “Fabrication and errors in the bibliographic "
       "citations generated by ChatGPT,” Sci. Rep., vol. 13, 2023, "
       "doi: 10.1038/s41598-023-41032-5.")


def pair(ref_number: int = 1) -> CitationPair:
    return CitationPair(pair_id=f"p{ref_number}", claim_text="ChatGPT 會捏造引用。",
                        citation_marker=f"[{ref_number}]", ref_number=ref_number, ref_raw=REF)


class FakeFetcher:
    def __init__(self, result: FullTextResult, by_doi: dict[str, FullTextResult] | None = None) -> None:
        self.result = result
        self.by_doi = by_doi or {}
        self.calls = 0
        self.seen: list[str] = []

    def fetch(self, meta):
        self.calls += 1
        self.seen.append(meta.doi or meta.arxiv_id or meta.title)
        return self.by_doi.get(meta.doi, self.result)


class FakeLookup:
    def __init__(self, result: ReferenceLookupResult) -> None:
        self.result = result
        self.calls = 0
        self.seen: list[str] = []

    def lookup(self, pair: CitationPair) -> ReferenceLookupResult:
        self.calls += 1
        self.seen.append(pair.ref_raw)
        return self.result


def full_text_ok() -> FullTextResult:
    return FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="# Paper\n\nBody.",
                          source="europe_pmc_xml", url="https://example.org/x",
                          converter="jats", note="")


def abstract_ok() -> ReferenceLookupResult:
    return ReferenceLookupResult(ref_number=1, title="Fabrication and errors",
                                 abstract="We checked 636 citations.",
                                 source_status=SourceStatus.GOT_ABSTRACT,
                                 abstract_source="semantic_scholar",
                                 abstract_url="https://api.semanticscholar.org/x",
                                 source_note="Semantic Scholar 用 DOI 找到")


def test_full_text_wins_and_skips_the_abstract_lookup():
    fetcher, lookup = FakeFetcher(full_text_ok()), FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.FULL_TEXT
    assert evidence.text == "# Paper\n\nBody."
    assert evidence.source == "europe_pmc_xml"
    assert evidence.converter == "jats"
    assert evidence.has_evidence is True
    assert lookup.calls == 0  # 拿到全文就不要再花一次查摘要的額度


def test_falls_back_to_the_abstract_when_there_is_no_full_text():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS,
                                         note="沒有可用的開放存取位置"))
    lookup = FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT
    assert evidence.text == "We checked 636 citations."
    assert evidence.source == "semantic_scholar"
    assert evidence.converter == ""
    assert lookup.calls == 1


def test_no_evidence_at_all_is_marked_unverifiable():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.NOT_FOUND,
                                              source_note="兩個資料庫都查無"))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.UNAVAILABLE
    assert evidence.unverifiable is True
    assert evidence.text == ""


def test_note_keeps_the_two_reasons_apart():
    """下載失敗和查不到是兩件事，不可以併成一句。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.FETCH_FAILED,
                                         note="PDF 下載失敗（HTTP 429）"))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.LOOKUP_FAILED,
                                              source_note="Semantic Scholar 限流"))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert "全文：全文下載失敗（PDF 下載失敗（HTTP 429））" in evidence.note
    assert "摘要：查詢失敗（Semantic Scholar 限流）" in evidence.note
    assert evidence.unverifiable is True


def test_missing_converter_still_falls_back_to_the_abstract():
    """缺 docling 是我們的問題，note 要講得出來，不可以只說沒有全文。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_CONVERTER,
                                         source="oa_pdf", url="https://example.org/a.pdf",
                                         note="本機沒有安裝 docling，PDF 轉不了（不是文獻的問題）"))
    lookup = FakeLookup(abstract_ok())

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT  # 仍然退摘要，不是直接放棄
    assert "缺少轉檔工具" in evidence.note
    assert "docling" in evidence.note


def test_both_methods_get_the_same_evidence():
    """同一筆 ref 只解析一次；A、B 拿到不同證據正是 11/24 分歧的來源之一。"""

    fetcher, lookup = FakeFetcher(full_text_ok()), FakeLookup(abstract_ok())
    resolver = EvidenceResolver(fetcher, lookup)

    for_method_a = resolver.resolve(pair())
    for_method_b = resolver.resolve(pair())

    assert for_method_a == for_method_b  # 評估腳本要能用 == 自我檢查 A／B 證據一致
    assert for_method_a.text == for_method_b.text
    assert for_method_a.basis is for_method_b.basis
    assert for_method_b.reused is True
    assert fetcher.calls == 1
    assert lookup.calls == 0


ISIK_REF = ("[1] M. Isik and S. Guleryuzlu, “A large language model pipeline for automated "
            "citation quality scoring,” Sci. Rep., vol. 16, 2026, doi: 10.1038/s41598-026-60947-3.")


def test_same_reference_under_two_numbers_is_resolved_once():
    """同一份書目被登錄成 [1] 和 [17]，不該查兩次。"""

    fetcher, lookup = FakeFetcher(full_text_ok()), FakeLookup(abstract_ok())
    resolver = EvidenceResolver(fetcher, lookup)

    resolver.resolve(pair(1))
    resolver.resolve(pair(17))

    assert fetcher.calls == 1


def test_same_ref_number_in_a_different_paper_is_not_reused():
    """最嚴重的那個 bug：跑第二篇論文時，它的 [1] 不可以拿到第一篇 [1] 的全文。"""

    walters = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="WALTERS FULL TEXT",
                             source="europe_pmc_xml", url="u1", converter="jats")
    isik = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="ISIK FULL TEXT",
                          source="oa_pdf", url="u2", converter="docling")
    fetcher = FakeFetcher(walters, by_doi={"10.1038/s41598-026-60947-3": isik})
    resolver = EvidenceResolver(fetcher, FakeLookup(abstract_ok()))

    first = resolver.resolve(pair(1))
    second = resolver.resolve(CitationPair(pair_id="b1", claim_text="x", citation_marker="[1]",
                                           ref_number=1, ref_raw=ISIK_REF))

    assert first.text == "WALTERS FULL TEXT"
    assert second.text == "ISIK FULL TEXT"
    assert second.reused is False
    assert fetcher.calls == 2


def test_the_fetcher_receives_this_pair_s_own_bibliography():
    fetcher = FakeFetcher(full_text_ok())
    EvidenceResolver(fetcher, FakeLookup(abstract_ok())).resolve(pair())

    assert fetcher.seen == ["10.1038/s41598-023-41032-5"]


def test_clear_allows_a_retry_after_a_transient_failure():
    """限流後重試：失敗會被記住（A、B 要同一份），所以要先 clear 才查得到。"""

    class Flaky:
        def __init__(self) -> None:
            self.calls = 0

        def fetch(self, meta):
            self.calls += 1
            if self.calls == 1:
                return FullTextResult(status=FullTextStatus.FETCH_FAILED, note="HTTP 429")
            return full_text_ok()

    fetcher = Flaky()
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.LOOKUP_FAILED))
    resolver = EvidenceResolver(fetcher, lookup)

    assert resolver.resolve(pair()).unverifiable is True
    assert resolver.resolve(pair()).unverifiable is True  # 同一次執行內 A、B 看到同一份
    resolver.clear()

    assert resolver.resolve(pair()).basis is EvidenceBasis.FULL_TEXT


def test_a_string_source_status_does_not_crash_the_note():
    """adapter 從 JSON 還原時 source_status 可能是純字串，不可以讓 resolve 炸掉。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    broken = ReferenceLookupResult(ref_number=1, title="t", abstract="an abstract",
                                   source_status="拿到摘要")  # type: ignore[arg-type]

    evidence = EvidenceResolver(fetcher, FakeLookup(broken)).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT
    assert "拿到摘要" in evidence.note


def test_abstract_without_a_source_name_is_flagged():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t", abstract="an abstract",
                                              source_status=SourceStatus.GOT_ABSTRACT))

    evidence = EvidenceResolver(fetcher, FakeLookup(lookup.result)).resolve(pair())

    assert evidence.basis is EvidenceBasis.ABSTRACT
    assert "沒有附來源名稱" in evidence.note


def test_internal_errors_are_not_filed_as_rate_limiting():
    class Exploding:
        def fetch(self, meta):
            raise AttributeError("our own bug")

    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.NOT_FOUND))
    evidence = EvidenceResolver(Exploding(), lookup).resolve(pair())

    assert evidence.full_text is not None
    assert evidence.full_text.status is FullTextStatus.INTERNAL_ERROR
    assert evidence.full_text.status is not FullTextStatus.FETCH_FAILED


def test_a_mismatched_ref_number_from_the_adapter_is_flagged():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=99, title="t",
                                              source_status=SourceStatus.NOT_FOUND))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair(1))

    assert "ref 編號" in evidence.note and "99" in evidence.note


def test_a_disk_cache_hit_is_visible_in_the_note():
    hit = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown="body",
                         source="arxiv_html", url="u", converter="trafilatura", cache_hit=True)

    evidence = EvidenceResolver(FakeFetcher(hit), FakeLookup(abstract_ok())).resolve(pair())

    assert "沿用先前存下的全文" in evidence.note


@pytest.mark.parametrize("failing", ["fulltext", "lookup"])
def test_unexpected_exceptions_do_not_escape(failing: str):
    class Exploding:
        def fetch(self, meta):
            raise RuntimeError("boom")

        def lookup(self, pair):
            raise RuntimeError("boom")

    fetcher = Exploding() if failing == "fulltext" else FakeFetcher(
        FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = Exploding() if failing == "lookup" else FakeLookup(
        ReferenceLookupResult(ref_number=1, title="t", source_status=SourceStatus.NOT_FOUND))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.unverifiable is True
    assert "RuntimeError" in evidence.note


def test_abstract_present_but_empty_counts_as_no_evidence():
    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t", abstract="   ",
                                              source_status=SourceStatus.GOT_ABSTRACT))

    evidence = EvidenceResolver(fetcher, lookup).resolve(pair())

    assert evidence.basis is EvidenceBasis.UNAVAILABLE


def test_retrieve_returns_both_the_evidence_and_the_passages():
    """判斷端只要呼叫一個方法：拿證據＋在證據裡找到的段落。"""

    from src.evidence_retrieval import RetrievalStatus

    source = ("# Paper\n\n## Results\n\nGPT-3.5 produced 55% fabricated citations in the "
              "evaluated literature reviews.\n")
    full = FullTextResult(status=FullTextStatus.GOT_FULL_TEXT, markdown=source,
                          source="europe_pmc_xml", url="u", converter="jats")
    claim = "GPT-3.5 produced 55% fabricated citations [1]."
    citation = CitationPair(pair_id="p1", claim_text=claim, citation_marker="[1]",
                            ref_number=1, ref_raw=REF)

    evidence, retrieval = EvidenceResolver(FakeFetcher(full), FakeLookup(abstract_ok())).retrieve(citation)

    assert evidence.basis is EvidenceBasis.FULL_TEXT
    assert retrieval.status is RetrievalStatus.FOUND
    assert "55% fabricated citations" in retrieval.passages[0].text


def test_retrieve_without_any_evidence_says_so():
    from src.evidence_retrieval import RetrievalStatus

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(ref_number=1, title="t",
                                              source_status=SourceStatus.NOT_FOUND))
    citation = CitationPair(pair_id="p1", claim_text="Anything at all [1].",
                            citation_marker="[1]", ref_number=1, ref_raw=REF)

    evidence, retrieval = EvidenceResolver(fetcher, lookup).retrieve(citation)

    assert evidence.unverifiable is True
    assert retrieval.status is RetrievalStatus.NO_SOURCE_TEXT


def test_retrieve_labels_whether_the_source_was_full_text_or_an_abstract():
    """摘要上的「只有零星字詞相符」意義不同，呼叫端要看得出來。"""

    fetcher = FakeFetcher(FullTextResult(status=FullTextStatus.NO_OPEN_ACCESS))
    lookup = FakeLookup(ReferenceLookupResult(
        ref_number=1, title="t", abstract="We checked 636 citations generated by ChatGPT.",
        source_status=SourceStatus.GOT_ABSTRACT, abstract_source="semantic_scholar"))
    citation = CitationPair(pair_id="p1", claim_text="ChatGPT generated 636 citations [1].",
                            citation_marker="[1]", ref_number=1, ref_raw=REF)

    evidence, retrieval = EvidenceResolver(fetcher, lookup).retrieve(citation)

    assert evidence.basis is EvidenceBasis.ABSTRACT
    assert retrieval.source_label == "摘要"


# ---------- 沒有識別碼時用 Crossref 比對補上（2026-11-28） ----------
# 實測：7,294 筆真實書目裡本機 regex 只抽得到 26% 的篇名，作者年份制沒有統一標準。
# 比對層把整條原文丟給 Crossref，再用本機抽到的作者與年份獨立驗證。

NO_DOI_REF = ("Anna Abalkina and Dorothy Bishop. 2023. Paper mills: a novel form of "
              "publishing malpractice affecting psychology. Meta-Psychology, 7.")


def no_doi_pair() -> CitationPair:
    return CitationPair(pair_id="p9", claim_text="論文工廠是一種新型態的出版不當行為。",
                        citation_marker="(Abalkina & Bishop, 2023)", ref_number=9,
                        ref_raw=NO_DOI_REF)


class FakeHttp:
    def __init__(self, item: dict | None, *, status: int = 200, error: str = "") -> None:
        self.item, self.status, self.error = item, status, error
        self.calls: list[dict] = []

    def get(self, url, params=None, headers=None):
        self.calls.append(params or {})
        if self.error or self.status != 200:
            return self.status, None, self.error
        return 200, {"message": {"items": [self.item] if self.item else []}}, ""


def crossref_item(score=150.0, families=("Abalkina", "Bishop")):
    return {"title": ["Paper mills: a novel form of publishing malpractice affecting psychology"],
            "score": score, "DOI": "10.15626/MP.2022.3422",
            "issued": {"date-parts": [[2023]]},
            "author": [{"family": f} for f in families]}


def matching_resolver(http, *, full=None, **kwargs):
    lookup = FakeLookup(abstract_ok())
    lookup.http = http
    fetcher = FakeFetcher(full or FullTextResult(status=FullTextStatus.NO_IDENTIFIER))
    return EvidenceResolver(fetcher, lookup, **kwargs), fetcher, lookup


def test_a_confirmed_match_supplies_the_doi_to_the_full_text_fetcher():
    """比對的真正價值是拿到 DOI：有 DOI 才查得到開放存取位置。"""
    http = FakeHttp(crossref_item())
    resolver, fetcher, _ = matching_resolver(http)

    evidence = resolver.resolve(no_doi_pair())

    assert fetcher.seen == ["10.15626/mp.2022.3422"], "取全文那層要收到比對補上的 DOI"
    assert "書目比對" in evidence.note
    assert len(http.calls) == 1


def test_a_reference_that_already_has_a_doi_is_not_sent_to_crossref():
    """有識別碼就不要浪費一次請求，Crossref 公開池每秒只能一次。"""
    http = FakeHttp(crossref_item())
    resolver, _, _ = matching_resolver(http, full=full_text_ok())

    resolver.resolve(pair())

    assert http.calls == []


def test_an_unconfirmed_match_leaves_the_metadata_alone_and_says_why():
    http = FakeHttp(crossref_item(families=("Totally", "Different")))
    resolver, fetcher, _ = matching_resolver(http)

    evidence = resolver.resolve(no_doi_pair())

    assert fetcher.seen == [""] or "10.15626" not in fetcher.seen[0], "沒驗證過的 DOI 不可以用"
    assert "書目比對未採用" in evidence.note
    assert "第一作者" in evidence.note


def test_a_broken_matcher_does_not_fail_the_whole_resolution():
    """比對層壞掉要退回本機解析，不可以讓整筆取證失敗。"""
    http = FakeHttp(None, status=500, error="boom")
    resolver, _, _ = matching_resolver(http)

    evidence = resolver.resolve(no_doi_pair())

    assert evidence.basis in (EvidenceBasis.ABSTRACT, EvidenceBasis.UNAVAILABLE)
    assert "書目比對未採用" in evidence.note


def test_the_same_reference_is_only_matched_once():
    http = FakeHttp(crossref_item())
    resolver, _, _ = matching_resolver(http)

    resolver.resolve(no_doi_pair())
    resolver.clear()                      # 清掉證據快取，比對結果仍要沿用
    resolver.resolve(no_doi_pair())

    assert len(http.calls) == 1, "同一條書目不可以查兩次 Crossref"


def test_matching_can_be_turned_off():
    http = FakeHttp(crossref_item())
    resolver, _, _ = matching_resolver(http, match_references=False)

    evidence = resolver.resolve(no_doi_pair())

    assert http.calls == []
    assert "書目比對" not in evidence.note


def test_a_matcher_that_raises_does_not_fail_the_whole_resolution():
    """HTTP 錯誤比對層自己會處理；這裡測的是它**自己壞掉**（丟例外）的情況。"""
    class Exploding:
        calls = 0

        def get(self, url, params=None, headers=None):
            Exploding.calls += 1
            raise RuntimeError("boom")

    lookup = FakeLookup(abstract_ok())
    lookup.http = Exploding()
    resolver = EvidenceResolver(FakeFetcher(FullTextResult(status=FullTextStatus.NO_IDENTIFIER)), lookup)

    evidence = resolver.resolve(no_doi_pair())

    assert Exploding.calls == 1
    assert "書目比對發生錯誤（RuntimeError）" in evidence.note
    assert evidence.basis in (EvidenceBasis.ABSTRACT, EvidenceBasis.UNAVAILABLE)
